    vector<ll> x_powers;
    ll cur = 1;
    while (cur <= r) {
        x_powers.push_back(cur);
        if (cur > r / x) break;
        cur *= x;
    }

    // Generate all possible values of y^b that are <= r
    vector<ll> y_powers;
    cur = 1;
    while (cur <= r) {
        y_powers.push_back(cur);
        if (cur > r / y) break;
        cur *= y;
    }

    // Generate all unlucky years
    set<ll> unlucky;
    for (ll xp : x_powers) {
        for (ll yp : y_powers) {
            ll sum = xp + yp;
            if (sum >= l && sum <= r) {
                unlucky.insert(sum);
            }
        }
    }

    // Now find the maximum gap between consecutive unlucky years
    // Also consider the gaps before the first unlucky year and after the last unlucky year

    if (unlucky.empty()) {
        // All years in [l, r] are lucky
        cout << r - l + 1 << endl;
        return 0;
    }

    ll max_gap = 0;

    // Gap before the first unlucky year
    ll first_unlucky = *unlucky.begin();
    if (first_unlucky > l) {
        max_gap = max(max_gap, first_unlucky - l);
    }

    // Gaps between consecutive unlucky years
    auto it = unlucky.begin();
    auto next_it = next(it);
    while (next_it != unlucky.end()) {
        ll gap = *next_it - *it - 1;
        max_gap = max(max_gap, gap);
        it = next_it;
        next_it = next(it);
    }

    // Gap after the last unlucky year
    ll last_unlucky = *unlucky.rbegin();
    if (last_unlucky < r) {
        max_gap = max(max_gap, r - last_unlucky);
    }

    cout << max_gap << endl;

    return 0;
